use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "oranda")]
#[command(about = "🎁 generate beautiful landing pages for your projects", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,

    /// Whether to output more detailed debug information
    #[arg(short, long, global = true)]
    verbose: bool,

    /// The format of the output
    #[arg(long, global = true, default_value = "human")]
    output_format: String,
}

#[derive(Subcommand)]
enum Commands {
    /// Build an oranda site
    Build {
        /// Only build the artifacts JSON file (if applicable) and other files that may be used to support it, such as installer source files
        #[arg(long)]
        json_only: bool,
    },
    /// Start a local development server that recompiles your oranda site if a file changes
    Dev {
        /// The port for the file server to be launched on
        #[arg(long)]
        port: Option<u16>,

        /// Skip the first build before starting to watch for changes
        #[arg(long)]
        no_first_build: bool,

        /// List of extra paths to watch
        #[arg(short, long)]
        include_paths: Vec<String>,
    },
    /// Start a file server to access your oranda site in a browser
    Serve {
        #[arg(long, default_value_t = 7979)]
        port: u16,
    },
    /// Generate infrastructure files for oranda sites
    Generate {
        #[command(subcommand)]
        command: GenerateCommands,

        /// Path to the output file
        #[arg(short, long)]
        output_path: Option<String>,

        /// Path to your oranda site
        #[arg(short, long)]
        site_path: Option<String>,
    },
}

#[derive(Subcommand)]
enum GenerateCommands {
    /// Generates a CI file that can be used to deploy your site
    Ci {
        /// What CI to generate a file for
        #[arg(long, default_value = "github")]
        ci: String,
    },
}

#[tokio::main]
async fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::Build { json_only } => {
            if cli.verbose {
                println!("↪ >o_o< DEBUG: No config found, using default values");
            }
            // Implementation...
            println!("✓ >o_o< SUCCESS: Your site build is located in `public`.");
        }
        Commands::Dev { port, no_first_build, include_paths } => {
             println!("↪ >o_o< INFO: Found {} paths to watch, starting watch...", include_paths.len() + 1);
             let p = port.unwrap_or(7979);
             println!("✓ >o_o< SUCCESS: Your project is available at: http://127.0.0.1:{}", p);
        }
        Commands::Serve { port } => {
             println!("✓ >o_o< SUCCESS: Your project is available at: http://127.0.0.1:{}", port);
        }
        Commands::Generate { command, output_path, site_path } => {
            match command {
                GenerateCommands::Ci { ci } => {
                    println!("↪ >o_o< INFO: Generating a CI deploy workflow for your site...");
                    // Implementation...
                }
            }
        }
    }
}
EOF
"}

