use clap::{Parser, Subcommand};
use std::path::Path;
use axum::{Router, routing::get_service, http::StatusCode};
use tower_http::services::ServeDir;
use std::net::SocketAddr;
use notify::{Watcher, RecursiveMode, watcher};
use std::sync::mpsc::channel;
use std::time::Duration;

#[derive(Parser)]
#[command(name = "oranda")]
#[command(about = "🎁 generate beautiful landing pages for your projects", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,

    #[arg(short, long, global = true)]
    verbose: bool,

    #[arg(long, global = true, default_value = "human")]
    output_format: String,
}

#[derive(Subcommand)]
enum Commands {
    Build {
        #[arg(long)]
        json_only: bool,
    },
    Dev {
        #[arg(long)]
        port: Option<u16>,
        #[arg(long)]
        no_first_build: bool,
        #[arg(short, long)]
        include_paths: Vec<String>,
    },
    Serve {
        #[arg(long, default_value_t = 7979)]
        port: u16,
    },
    Generate {
        #[command(subcommand)]
        command: GenerateCommands,
        #[arg(short, long)]
        output_path: Option<String>,
        #[arg(short, long)]
        site_path: Option<String>,
    },
}

#[derive(Subcommand)]
enum GenerateCommands {
    Ci {
        #[arg(long, default_value = "github")]
        ci: String,
    },
}

async fn run_serve(port: u16) {
    let app = Router::new().nest_service(
        "/",
        get_service(ServeDir::new("public")).handle_error(|_| async {
            (StatusCode::INTERNAL_SERVER_ERROR, "Internal Server Error")
        }),
    );

    let addr = SocketAddr::from(([127, 0, 0, 1], port));
    println!("✓ >o_o< SUCCESS: Your project is available at: http://{}", addr);

    axum::Server::bind(&addr)
        .serve(app.into_make_service())
        .await
        .unwrap();
}

fn do_build(verbose: bool, json_only: bool) {
    if verbose {
        println!("↪ >o_o< DEBUG: No config found, using default values");
    }
    // Simulate build
    std::fs::create_dir_all("public").unwrap();
    // Copy/create favicon if needed
    // std::fs::write("public/favicon.ico", ...).unwrap();

    if !json_only {
        std::fs::write("public/index.html", "<html><body><h1>Oranda Repro</h1></body></html>").unwrap();
    }
    println!("✓ >o_o< SUCCESS: Your site build is located in `public`.");
}

#[tokio::main]
async fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::Build { json_only } => {
            do_build(cli.verbose, json_only);
        }
        Commands::Serve { port } => {
            run_serve(port).await;
        }
        Commands::Dev { port, no_first_build, include_paths } => {
            if !no_first_build {
                do_build(cli.verbose, false);
            }
            let p = port.unwrap_or(7979);
            println!("↪ >o_o< INFO: Found {} paths to watch, starting watch...", include_paths.len() + 1);
            run_serve(p).await;
        }
        Commands::Generate { command, output_path, site_path } => {
            match command {
                GenerateCommands::Ci { ci } => {
                    println!("↪ >o_o< INFO: Generating a CI deploy workflow for your site...");
                    // Just a mock CI file
                    let ci_content = "name: Deploy site\non: push:\n  branches: [main]\n";
                    if let Some(path) = output_path {
                        let path = Path::new(&path);
                        if let Some(parent) = path.parent() {
                            std::fs::create_dir_all(parent).unwrap();
                        }
                        std::fs::write(path, ci_content).unwrap();
                    }
                }
            }
        }
    }
}
EOF
"}

