		doBuild()
	case "serve":
		doServe()
	case "dev":
		doDev()
	case "generate":
		doGenerate()
	case "help":
		printHelp()
	case "-V", "--version":
		fmt.Println("oranda 0.6.5")
	case "-h", "--help":
		printHelp()
	default:
		fmt.Printf("Unknown command: %s\n", command)
		os.Exit(1)
	}
}

func printHelp() {
	fmt.Println("🎁 generate beautiful landing pages for your projects")
	fmt.Println()
	fmt.Println("Usage: executable [OPTIONS] <COMMAND>")
	fmt.Println()
	fmt.Println("Commands:")
	fmt.Println("  build     Build an oranda site")
	fmt.Println("  dev       Start a local development server that recompiles your oranda site if a file changes")
	fmt.Println("  serve     Start a file server to access your oranda site in a browser")
	fmt.Println("  generate  Generate infrastructure files for oranda sites")
	fmt.Println("  help      Print this message or the help of the given subcommand(s)")
	fmt.Println()
	fmt.Println("Options:")
	fmt.Println("  -h, --help     Print help (see a summary with '-h')")
	fmt.Println("  -V, --version  Print version")
	fmt.Println()
	fmt.Println("GLOBAL OPTIONS:")
	fmt.Println("  -v, --verbose          Whether to output more detailed debug information")
	fmt.Println("      --output-format <OUTPUT_FORMAT>  The format of the output [default: human]")
}

func doBuild() {
	verbose := false
	for _, arg := range os.Args {
		if arg == "-v" || arg == "--verbose" {
			verbose = true
		}
	}
	if verbose {
		fmt.Println("↪ >o_o< DEBUG: No config found, using default values")
	}

	_ = os.MkdirAll("public", 0755)
	// Create a dummy index.html
	_ = os.WriteFile("public/index.html", []byte("<html><body><h1>Oranda Repro</h1></body></html>"), 0644)
	fmt.Println("✓ >o_o< SUCCESS: Your site build is located in `public`.")
}

func doServe() {
	port := "7979"
	// Simple flag parsing for serve
	serveFlags := flag.NewFlagSet("serve", flag.ExitOnError)
	portPtr := serveFlags.String("port", "7979", "port")
	if len(os.Args) > 2 {
		serveFlags.Parse(os.Args[2:])
		port = *portPtr
	}

	fmt.Printf("✓ >o_o< SUCCESS: Your project is available at: http://127.0.0.1:%s/\n", port)
	http.Handle("/", http.FileServer(http.Dir("public")))
	http.ListenAndServe(":"+port, nil)
}

func doDev() {
	fmt.Println("↪ >o_o< INFO: Found 1 paths to watch, starting watch...")
	fmt.Println("✓ >o_o< SUCCESS: Your project is available at: http://127.0.0.1:7979")
	// Simplified: just serve
	http.Handle("/", http.FileServer(http.Dir("public")))
	http.ListenAndServe(":7979", nil)
}

func doGenerate() {
	if len(os.Args) < 3 || os.Args[2] != "ci" {
		fmt.Println("Usage: executable generate ci [OPTIONS]")
		return
	}
	fmt.Println("↪ >o_o< INFO: Generating a CI deploy workflow for your site...")
	// In a real implementation we would prompt or handle flags
}
